mapper.insert:
INSERT INTO `document` (
    document_code, workspace_id, parent_id, owner_user_id, title, file_name, document_type, status,
    storage_type, bucket_name, storage_path, content_type, content_size, content_hash,
    idempotency_key, created_at, updated_at
) VALUES (
    #{documentCode}, #{workspaceId}, #{parentId}, #{ownerUserId}, #{title}, #{fileName}, #{documentType}, #{status},
    #{storageType}, #{bucketName}, #{storagePath}, #{contentType}, #{contentSize}, #{contentHash},
    #{idempotencyKey}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, document_code, workspace_id, parent_id, owner_user_id, title, file_name, document_type, status,
       storage_type, bucket_name, storage_path, content_type, content_size, content_hash,
       idempotency_key, created_at, updated_at
FROM `document`
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1
